5.3 Programa Vulnerable
#include &lt;stdlib.h&gt;
#include &lt;stdio.h&gt;
#include &lt;string.h&gt;

int bowfunc(char *string) {
    char buffer[1024];
    strcpy(buffer, string);  // Vulnerable - no bounds check
    return 1;
}

int main(int argc, char *argv[]) {
    bowfunc(argv[1]);
    printf("Done.\n");
    return 1;
}
